 29	import java.util.concurrent.ScheduledFuture;
 30	import java.util.concurrent.TimeUnit;
 31	import java.util.concurrent.atomic.AtomicReference;
 32	import java.util.concurrent.atomic.AtomicReferenceFieldUpdater;
 33	
 34	import static java.util.Collections.singletonList;
 35	
 36	/**
 37	 * Abstract cache that automatically removes entries for a hostname once the TTL for an entry is reached.
 38	 *
 39	 * @param <E>
 40	 */
 41	abstract class Cache<E> {
 42	    private static final AtomicReferenceFieldUpdater<Cache.Entries, ScheduledFuture> FUTURE_UPDATER =
 43	            AtomicReferenceFieldUpdater.newUpdater(Cache.Entries.class, ScheduledFuture.class, "expirationFuture");
 44	
 45	    private static final ScheduledFuture<?> CANCELLED = new ScheduledFuture<Object>() {
 46	
 47	        @Override
 48	        public boolean cancel(boolean mayInterruptIfRunning) {
 49	            return false;
 50	        }
 51	
 52	        @Override
 53	        public long getDelay(TimeUnit unit) {
 54	            // We ignore unit and always return the minimum value to ensure the TTL of the cancelled marker is
 55	            // the smallest.
 56	            return Long.MIN_VALUE;
 57	        }
 58	
 59	        @Override
 60	        public int compareTo(Delayed o) {
 61	            throw new UnsupportedOperationException();
 62	        }
 63	
 64	        @Override
 65	        public boolean isCancelled() {
 66	            return true;
 67	        }
 68	
 69	        @Override
 70	        public boolean isDone() {
 71	            return true;
 72	        }
 73	
 74	        @Override
 75	        public Object get() {
 76	            throw new UnsupportedOperationException();
 77	        }
 78	
 79	        @Override
 80	        public Object get(long timeout, TimeUnit unit) {
 81	            throw new UnsupportedOperationException();
 82	        }
 83	    };
 84	
 85	    // Two years are supported by all our EventLoop implementations and so safe to use as maximum.
 86	    // See also: https://github.com/netty/netty/commit/b47fb817991b42ec8808c7d26538f3f2464e1fa6
 87	    static final int MAX_SUPPORTED_TTL_SECS = (int) TimeUnit.DAYS.toSeconds(365 * 2);
 88	
 89	    private final ConcurrentMap<String, Entries> resolveCache = new ConcurrentHashMap<>();
 90	
 91	    /**
 92	     * Remove everything from the cache.
 93	     */
 94	    final void clear() {
 95	        while (!resolveCache.isEmpty()) {
 96	            for (Iterator<Entry<String, Entries>> i = resolveCache.entrySet().iterator(); i.hasNext();) {
 97	                Map.Entry<String, Entries> e = i.next();
 98	                i.remove();
 99	
100	                e.getValue().clearAndCancel();
101	            }
102	        }
103	    }
104	
105	    /**
106	     * Clear all entries (if anything exists) for the given hostname and return {@code true} if anything was removed.
107	     */
108	    final boolean clear(String hostname) {
109	        Entries entries = resolveCache.remove(hostname);
110	        return entries != null && entries.clearAndCancel();
111	    }
112	
113	    /**
114	     * Returns all caches entries for the given hostname.
115	     */
116	    final List<? extends E> get(String hostname) {
117	        Entries entries = resolveCache.get(hostname);
118	        return entries == null ? null : entries.get();
119	    }
120	
121	    /**
122	     * Cache a value for the given hostname that will automatically expire once the TTL is reached.
123	     */
124	    final void cache(String hostname, E value, int ttl, EventLoop loop) {
125	        for (;;) {
126	            Entries entries = resolveCache.get(hostname);
127	            if (entries == null) {
128	                entries = new Entries(hostname);
129	                Entries oldEntries = resolveCache.putIfAbsent(hostname, entries);
130	                if (oldEntries != null) {
131	                    entries = oldEntries;
132	                }
133	            }
134	            if (entries.add(value, ttl, loop)) {
135	                break;
136	            }
137	            // Entries was concurrently evicted (CANCELLED state); retry with a fresh lookup.
138	        }
139	    }
140	
141	    /**
142	     * Return the number of hostnames for which we have cached something.
143	     */
144	    final int size() {
145	        return resolveCache.size();
146	    }
147	
148	    /**
149	     * Returns {@code true} if this entry should replace all other entries that are already cached for the hostname.
150	     */
151	    protected abstract boolean shouldReplaceAll(E entry);
152	
153	    /**
154	     * Sort the {@link List} for a {@code hostname} before caching these.
155	     */
156	    protected void sortEntries(
157	            @SuppressWarnings("unused") String hostname, @SuppressWarnings("unused") List<E> entries) {
158	        // NOOP.
159	    }
160	
161	    /**
162	     * Returns {@code true} if both entries are equal.
163	     */
164	    protected abstract boolean equals(E entry, E otherEntry);
165	
166	    // Directly extend AtomicReference for intrinsics and also to keep memory overhead low.
167	    private final class Entries extends AtomicReference<List<E>> implements Runnable {
168	
169	        private final String hostname;
170	        // Needs to be package-private to be able to access it via the AtomicReferenceFieldUpdater
171	        volatile ScheduledFuture<?> expirationFuture;
172	
173	        Entries(String hostname) {
174	            super(Collections.<E>emptyList());
175	            this.hostname = hostname;
176	        }
177	
178	        boolean add(E e, int ttl, EventLoop loop) {
179	            if (!shouldReplaceAll(e)) {
180	                for (;;) {
181	                    List<E> entries = get();
182	                    if (!entries.isEmpty()) {
183	                        final E firstEntry = entries.get(0);
184	                        if (shouldReplaceAll(firstEntry)) {
185	                            assert entries.size() == 1;
186	
187	                            if (compareAndSet(entries, singletonList(e))) {
188	                                return scheduleCacheExpirationIfNeeded(ttl, loop);
189	                            } else {
190	                                // Need to try again as CAS failed
191	                                continue;
192	                            }
193	                        }
194	
195	                        // Create a new List for COW semantics
196	                        List<E> newEntries = new ArrayList<E>(entries.size() + 1);
197	                        int i = 0;
198	                        E replacedEntry = null;
199	                        do {
200	                            E entry = entries.get(i);
201	                            // Only add old entry if the address is not the same as the one we try to add as well.
202	                            // In this case we will skip it and just add the new entry as this may have
203	                            // more up-to-date data and cancel the old after we were able to update the cache.
204	                            if (!Cache.this.equals(e, entry)) {
205	                                newEntries.add(entry);
206	                            } else {
207	                                replacedEntry = entry;
208	                                newEntries.add(e);
209	
210	                                ++i;
211	                                for (; i < entries.size(); ++i) {
212	                                    newEntries.add(entries.get(i));
213	                                }
214	                                break;
215	                            }
216	                        } while (++i < entries.size());
217	                        if (replacedEntry == null) {
218	                            newEntries.add(e);
219	                        }
220	                        sortEntries(hostname, newEntries);
221	
222	                        if (compareAndSet(entries, Collections.unmodifiableList(newEntries))) {
223	                            return scheduleCacheExpirationIfNeeded(ttl, loop);
224	                        }
225	                    } else if (compareAndSet(entries, singletonList(e))) {
226	                        return scheduleCacheExpirationIfNeeded(ttl, loop);
227	                    }
228	                }
229	            } else {
230	                set(singletonList(e));
231	                return scheduleCacheExpirationIfNeeded(ttl, loop);
232	            }
233	        }
234	
235	        private boolean scheduleCacheExpirationIfNeeded(int ttl, EventLoop loop) {
236	            for (;;) {
237	                // We currently don't calculate a new TTL when we need to retry the CAS as we don't expect this to
238	                // be invoked very concurrently and also we use SECONDS anyway. If this ever becomes a problem
239	                // we can reconsider.
240	                ScheduledFuture<?> oldFuture = FUTURE_UPDATER.get(this);
241	                if (oldFuture == CANCELLED) {
242	                    // This Entries was already evicted from resolveCache by a concurrent expiration.
243	                    // Signal the caller (cache()) to retry with a fresh Entries.
244	                    return false;
245	                }
246	                if (oldFuture == null || oldFuture.getDelay(TimeUnit.SECONDS) > ttl) {
247	                    ScheduledFuture<?> newFuture = loop.schedule(this, ttl, TimeUnit.SECONDS);
248	                    // It is possible that
249	                    // 1. task will fire in between this line, or
250	                    // 2. multiple timers may be set if there is concurrency
251	                    // (1) If the task fires and sets CANCELLED before our CAS, the next loop iteration returns false.
252	                    // (2) This is a trade-off to avoid concurrency resulting in contention on a synchronized block.
253	                    if (FUTURE_UPDATER.compareAndSet(this, oldFuture, newFuture)) {
254	                        if (oldFuture != null) {
255	                            oldFuture.cancel(true);
256	                        }
257	                        return true;
258	                    } else {
259	                        // There was something else scheduled in the meantime... Cancel and try again.
260	                        newFuture.cancel(true);
261	                    }
262	                } else {
263	                    return true;
264	                }
265	            }
266	        }
267	
268	        boolean clearAndCancel() {
269	            List<E> entries = getAndSet(Collections.<E>emptyList());
270	            if (entries.isEmpty()) {
271	                return false;
272	            }
273	
274	            ScheduledFuture<?> expirationFuture = FUTURE_UPDATER.getAndSet(this, CANCELLED);
275	            if (expirationFuture != null) {
276	                expirationFuture.cancel(false);
277	            }
278	
279	            return true;
280	        }
281	
282	        @Override
283	        public void run() {
284	            // We always remove all entries for a hostname once one entry expire. This is not the
285	            // most efficient to do but this way we can guarantee that if a DnsResolver
286	            // be configured to prefer one ip family over the other we will not return unexpected
287	            // results to the enduser if one of the A or AAAA records has different TTL settings.
288	            //
289	            // As a TTL is just a hint of the maximum time a cache is allowed to cache stuff it's
290	            // completely fine to remove the entry even if the TTL is not reached yet.
291	            //
292	            // See https://github.com/netty/netty/issues/7329
293	            resolveCache.remove(hostname, this);
294	
295	            clearAndCancel();
296	        }
297	    }
298	}

