151	    private void expungeInvalidSessions() {
152	        assert Thread.holdsLock(sessions);
153	
154	        if (sessions.isEmpty()) {
155	            return;
156	        }
157	        long now = System.currentTimeMillis();
158	        Iterator<Map.Entry<HostPort, SessionHolder>> iterator = sessions.entrySet().iterator();
159	        while (iterator.hasNext()) {
160	            SessionHolder sessionHolder = iterator.next().getValue();
161	            if (!sessionHolder.isValid(now)) {
162	                iterator.remove();
163	            }
164	        }
165	    }
166	
167	    @Nullable
168	    private static HostPort keyFor(@Nullable String host, int port) {
169	        if (host == null && port < 1) {
170	            return null;
171	        }
172	        return new HostPort(host, port);
173	    }
174	
175	    private static final class SessionHolder {
176	        private final long creationTime;
